import java.util.*;
import java.util.stream.*;

public class Solution {
    record Venda(String categoria, String produto, double valor, int quantidade) {}

    static class Relatorio {
        private List<Venda> validas(List<Venda> vendas) {
            return vendas.stream()
                .filter(v -> v.categoria() != null && !v.categoria().isBlank())
                .filter(v -> v.valor() >= 0 && v.quantidade() > 0)
                .toList();
        }

        Map<String, Double> totalPorCategoria(List<Venda> vendas) {
            return validas(vendas).stream().collect(Collectors.groupingBy(
                Venda::categoria,
                Collectors.summingDouble(v -> v.valor() * v.quantidade())));
        }

        Optional<Venda> maiorVenda(List<Venda> vendas) {
            return validas(vendas).stream()
                .max(Comparator.comparingDouble(v -> v.valor() * v.quantidade()));
        }

        List<String> topCategorias(List<Venda> vendas, int n) {
            if (n <= 0) return List.of();
            return totalPorCategoria(vendas).entrySet().stream()
                .sorted(Map.Entry.<String, Double>comparingByValue().reversed()
                    .thenComparing(Map.Entry.comparingByKey()))
                .limit(n)
                .map(Map.Entry::getKey)
                .toList();
        }

        double ticketMedio(List<Venda> vendas) {
            var v = validas(vendas);
            return v.isEmpty() ? 0 : v.stream()
                .mapToDouble(x -> x.valor() * x.quantidade()).average().orElse(0);
        }
    }
}

