import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.List;

class SolutionTest {
    private final Solution.Relatorio r = new Solution.Relatorio();
    private final List<Solution.Venda> vendas = List.of(
        new Solution.Venda("A", "x", 10, 2),
        new Solution.Venda("A", "y", 5, 1),
        new Solution.Venda("B", "z", 7, 1));

    @Test void totalPorCategoria() {
        var t = r.totalPorCategoria(vendas);
        assertEquals(25.0, t.get("A"));
        assertEquals(7.0, t.get("B"));
    }

    @Test void maiorVenda() {
        assertEquals("x", r.maiorVenda(vendas).orElseThrow().produto());
    }

    @Test void topCategoriasComDesempate() {
        assertEquals(List.of("A", "B"), r.topCategorias(vendas, 2));
    }

    @Test void entradaVazia() {
        assertTrue(r.totalPorCategoria(List.of()).isEmpty());
        assertEquals(0, r.ticketMedio(List.of()));
    }
}
